def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = []
    op = []
    for a, b in history:
        my.append(a)
        op.append(b)

    tot_d = 0
    for x in op:
        if x == 'D':
            tot_d += 1
    tot_c = n - tot_d

    if n >= 10:
        recent = op[-10:]
    else:
        recent = op[:]
    rec_len = len(recent)
    rec_d = 0
    for x in recent:
        if x == 'D':
            rec_d += 1

    if n >= 20:
        rec20 = op[-20:]
    else:
        rec20 = op[:]
    rec20_len = len(rec20)
    rec20_d = 0
    for x in rec20:
        if x == 'D':
            rec20_d += 1

    after_d = 0
    after_dc = 0
    after_c = 0
    after_cc = 0
    for i in range(1, n):
        pm = history[i - 1][0]
        co = history[i][1]
        if pm == 'D':
            after_d += 1
            if co == 'C':
                after_dc += 1
        else:
            after_c += 1
            if co == 'C':
                after_cc += 1
    after_d_fail = after_d - after_dc

    last_m = history[-1][0]
    last_o = history[-1][1]
    if last_m == 'C':
        if last_o == 'C':
            state = 0
        else:
            state = 1
    else:
        if last_o == 'C':
            state = 2
        else:
            state = 3

    if n >= 75:
        num = [0.0] * 4
        den = [0.0] * 4
        mi = []
        oi = []
        for a, b in history:
            mi.append(0 if a == 'C' else 1)
            oi.append(0 if b == 'C' else 1)

        for i in range(n - 1):
            s = mi[i] * 2 + oi[i]
            den[s] += 1.0
            if oi[i + 1] == 0:
                num[s] += 1.0

        if after_c > 0:
            pc_given_c = float(after_cc) / float(after_c)
        else:
            pc_given_c = 0.8
        if after_d > 0:
            pc_given_d = float(after_dc) / float(after_d)
        else:
            pc_given_d = 0.18
        base = float(tot_c) / float(n)

        pr0 = max(0.75, min(0.95, 0.25 + 0.75 * pc_given_c))
        pr1 = max(0.35, min(0.85, 0.15 + 0.65 * pc_given_c))
        pr2 = max(0.05, min(0.95, pc_given_d))
        pr3 = max(0.10, min(0.85, 0.20 + 0.55 * base))

        priors = [pr0, pr1, pr2, pr3]
        q = [0.0] * 4
        for s in range(4):
            alpha = 2.0 if den[s] < 2.0 else 1.0
            val = (num[s] + priors[s] * alpha) / (den[s] + alpha)
            if val < 0.02:
                val = 0.02
            if val > 0.98:
                val = 0.98
            q[s] = val

        h = 100 - n
        V = [0.0] * 4
        for _ in range(h - 1):
            NV = [0.0] * 4
            for s in range(4):
                p = q[s]
                valC = p * (3.0 + V[0]) + (1.0 - p) * V[1]
                valD = p * (5.0 + V[2]) + (1.0 - p) * (1.0 + V[3])
                if valC > valD:
                    NV[s] = valC
                else:
                    NV[s] = valD
            V = NV

        p = q[state]
        valC = p * (3.0 + V[0]) + (1.0 - p) * V[1]
        valD = p * (5.0 + V[2]) + (1.0 - p) * (1.0 + V[3])
        if valD > valC:
            return 'D'
        return 'C'

    nice = (rec20_d <= max(2, int(rec20_len * 0.2))) and (tot_c * 5 >= n * 3)
    very_nice = (rec20_d <= 1) and (tot_c * 5 >= n * 4)
    hostile = (rec20_d * 2 >= rec20_len) or (tot_d * 2 >= n)

    p_tol = 0.15
    if after_d > 0:
        p_tol = float(after_dc) / float(after_d)

    exploitable = False
    if after_dc >= 3 and after_d_fail <= 1 and p_tol >= 0.6 and nice:
        exploitable = True
    if after_dc >= 2 and after_d_fail <= 1 and p_tol >= 0.65 and very_nice:
        exploitable = True
    if after_dc >= 1 and after_d_fail == 0 and rec20_d == 0 and nice:
        exploitable = True

    if hostile:
        if state == 3 and rec20_d < rec20_len and rng.random() < 0.1:
            return 'C'
        return 'D'

    if exploitable:
        if state == 1:
            if nice and (rec_d <= 2 or after_d_fail == 0) and rng.random() < 0.7:
                return 'C'
            return 'D'
        if state == 3:
            if rec20_d < rec20_len and rng.random() < 0.35:
                return 'C'
            return 'D'
        if rng.random() < 0.88:
            return 'D'
        return 'C'

    if very_nice:
        if state == 0:
            if after_dc >= 1 and after_d_fail == 0 and rec20_d == 0:
                return 'D'
            if after_dc >= 2 and after_d_fail <= 1 and rng.random() < 0.6:
                return 'D'
            if after_d == 0 and n >= 14:
                return 'D'
            return 'C'
        if state == 1:
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        if state == 2:
            if after_dc >= 1 and after_d_fail == 0 and rec20_d == 0:
                return 'D'
            if after_dc >= 2 and after_d_fail <= 1 and rng.random() < 0.7:
                return 'D'
            return 'C'
        if rec20_d < rec20_len and rng.random() < 0.45:
            return 'C'
        return 'D'

    if nice:
        if state == 0:
            if after_dc >= 2 and after_d_fail <= 1 and p_tol >= 0.55 and rng.random() < 0.55:
                return 'D'
            if after_d == 0 and n >= 20 and rng.random() < 0.04:
                return 'D'
            return 'C'
        if state == 1:
            if rec_d <= 2 and tot_c * 3 >= n * 2 and rng.random() < 0.7:
                return 'C'
            return 'D'
        if state == 2:
            if after_dc >= 2 and after_d_fail == 0 and p_tol >= 0.6 and rng.random() < 0.65:
                return 'D'
            return 'C'
        if rec20_d < rec20_len * 0.7 and rng.random() < 0.35:
            return 'C'
        return 'D'

    if state == 0:
        if tot_c * 4 >= n * 3 and rec_d <= 2 and after_d == 0 and n >= 25 and rng.random() < 0.03:
            return 'D'
        return 'C'

    if state == 1:
        if rec_d <= 1 and tot_c * 5 >= n * 3 and rng.random() < 0.65:
            return 'C'
        if after_dc > after_d_fail and rec_d <= 2 and rng.random() < 0.4:
            return 'C'
        return 'D'

    if state == 2:
        if after_dc >= 2 and after_d_fail <= 1 and rec_d <= 3 and rng.random() < 0.55:
            return 'D'
        if tot_c * 5 >= n * 4 and rec_d == 0 and rng.random() < 0.4:
            return 'D'
        return 'C'

    if rec20_d < rec20_len and after_dc >= 1 and rng.random() < 0.35:
        return 'C'
    if rec20_d <= 3 and rng.random() < 0.45:
        return 'C'
    return 'D'
